import { z } from "zod";
import { isoDateTimeSchema } from "./common";

/**
 * Entities the POS is allowed to push. Empty for now: sales and inventory will
 * be added here (and a matching handler registered on the server) once the POS
 * implements them. Keeping it as a const tuple lets the schema stay in sync.
 */
export const PUSH_ENTITIES = [] as const;

export type PushEntity = (typeof PUSH_ENTITIES)[number];

/**
 * A single record pushed from the POS outbox. `clientId` is generated by the
 * POS (UUID, ideally v7 for ordering) and is the idempotency key: the server
 * dedupes on (device, entity, clientId), so a retried item is never applied
 * twice. `payload` is validated per-entity by the matching server handler.
 */
export const pushItemSchema = z.object({
	clientId: z.string().min(1),
	entity: z.string().min(1),
	operation: z.enum(["create", "update", "delete"]),
	occurredAt: isoDateTimeSchema,
	payload: z.unknown(),
});

export type PushItem = z.infer<typeof pushItemSchema>;

export const pushRequestSchema = z.object({
	/** Client-generated batch id (UUID). Reused on retry for idempotency. */
	batchId: z.string().min(1),
	sentAt: isoDateTimeSchema,
	items: z.array(pushItemSchema).max(500),
});

export type PushRequest = z.infer<typeof pushRequestSchema>;

/** Outcome reported back to the POS for each pushed item. */
export const pushItemResultSchema = z.object({
	clientId: z.string(),
	status: z.enum(["accepted", "duplicate", "rejected"]),
	/** Present when `status` is "rejected". */
	errorCode: z.string().optional(),
	message: z.string().optional(),
});

export type PushItemResult = z.infer<typeof pushItemResultSchema>;

export const pushResponseSchema = z.object({
	batchId: z.string(),
	/** True when this exact batch was already processed before. */
	duplicateBatch: z.boolean(),
	accepted: z.number().int().nonnegative(),
	duplicates: z.number().int().nonnegative(),
	rejected: z.number().int().nonnegative(),
	results: z.array(pushItemResultSchema),
});

export type PushResponse = z.infer<typeof pushResponseSchema>;
